// 定义展馆器形、釉色与可键盘操作的控制面板。
export const galleryBody=`<section class="container page-intro gallery-intro"><div class="breadcrumb"><a href="@@index.html">首页</a><span>/</span><span>数字展馆</span></div><div class="gallery-title-row"><div><span class="section-kicker">观形 · 察色 · 识器</span><h1>器有形，意无尽。</h1><p>转一转器物，换一层釉色。让目光，沿着手的痕迹游走。</p></div><span class="gallery-badge">器形研究 · 可交互展陈</span></div></section><section class="container gallery-workspace"><aside class="object-list" aria-label="选择器物">${[['meiping','梅瓶','丰肩，收腹，敛足'],['yuhuchun','玉壶春瓶','撇口，细颈，垂腹'],['bowl','建盏','敞口，深腹，圈足'],['enamel','珐琅瓶','铜胎，金丝，珐琅']].map(([id,name,detail],i)=>`<button class="object-option ${i===0?'selected':''}" data-object="${id}" aria-pressed="${i===0}"><img src="@@assets/svg/${id}.svg" alt="${name}形制示意" width="80" height="80"><span><b>${name}</b><small>${detail}</small></span></button>`).join('')}</aside><div class="exhibit"><div class="exhibit-halo" aria-hidden="true"></div><span class="exhibit-corner">纹脉 · 器物档案<span id="object-code">WM-001</span></span><div class="fallback-card" id="fallback-card"><div class="fallback-front"><img id="fallback-image" src="@@assets/svg/meiping.svg" width="800" height="600" alt="梅瓶原创器形示意"></div><div class="fallback-back"><span class="section-kicker">器形笔记</span><h3 id="fallback-name">梅瓶</h3><p id="fallback-description">小口、短颈、丰肩与收腹，是梅瓶鲜明的轮廓语言。此为原创形制示意，不对应具体馆藏。</p></div></div><canvas id="vessel-canvas" aria-label="可旋转的三维器物，左右键旋转，上下键缩放，Home 复位" tabindex="0" hidden></canvas><div class="exhibit-ground" aria-hidden="true"></div><div class="exhibit-caption"><h2 id="object-name">梅瓶</h2><p id="object-caption">一肩盛山水，一釉藏春色。</p></div><div class="exhibit-hint"><span id="render-mode">器形意象</span><span>拖动旋转 · 滚轮缩放 · 双击复位</span></div><div class="exhibit-controls"><button class="pill" id="rotate-left">↶ 左转</button><button class="pill" id="reset-view">复位器物</button><button class="pill" id="rotate-right">右转 ↷</button><button class="pill" id="flip-card" hidden>翻看器形笔记</button></div></div><aside class="glaze-panel"><span class="section-kicker">釉色实验室</span><h2>一器，万般青。</h2><p>选择一种釉色，<br>看看光在表面留下什么。</p><div class="glaze-options" aria-label="选择釉色">${[['powder','粉青','#9bbca9'],['plum','梅子青','#4a7962'],['sky','天青','#8daaa5'],['hare','兔毫','#745637'],['star','曜变','#374d65']].map(([id,name,color],i)=>`<button class="glaze-option" data-glaze="${id}" aria-pressed="${i===0}"><span style="--swatch:${color}" aria-hidden="true"></span>${name}</button>`).join('')}</div><div class="glaze-divider"></div><label class="range-label" for="rotation-speed">旋转速度 <output id="speed-value">缓慢</output></label><input id="rotation-speed" type="range" min="0" max="100" value="18"><label class="wireframe-control"><input type="checkbox" id="wireframe">查看器形骨架</label><p class="source-note">釉色为数字艺术模拟，不作为真实配方或烧制效果的预测。</p><a class="text-link" href="@@craft/celadon.html">走近青瓷技艺 ↗</a></aside></section><section class="container gallery-note"><span class="note-symbol serif" aria-hidden="true">土</span><div><h2>从一条轮廓，到一件器物。</h2><p>这里没有下载来的三维模型。我们用半径与高度写下曲线，让它绕轴旋转，如同在数字世界中拉坯。每一件器物，都是一次对形制的观察。</p></div><a class="text-link" href="@@about.html#technology">阅读创作手记 ↗</a></section>`;
